def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease.append((0, int(ident)))  # numeric identifiers sort first
                else:
                    prerelease.append((1, ident))  # non-numeric identifiers sort second
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def sort_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # For sorting: version without prerelease sorts after version with prerelease
        # So we use (major, minor, patch, has_prerelease, prerelease)
        # If prerelease is None, we want it to sort after all prerelease versions
        if prerelease is None:
            return (major, minor, patch, 1)  # 1 means no prerelease (sorts after)
        else:
            return (major, minor, patch, 0, prerelease)  # 0 means has prerelease (sorts before)

    # Sort with stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

